// ============================================================
  // CHIBI MESH DATA (decimated Meshy.ai model — smooth per-vertex colors)
  // Strategy: weld UV-duplicate vertices on the full 260k-face mesh, average
  // texture colors per unique 3D point, THEN decimate. This sidesteps the
  // problem that Meshy's atlas is per-face-fragmented (incompatible with
  // decimation): by collapsing each 3D point's many atlas chunks down to one
  // averaged color BEFORE decimation, the colors interpolate smoothly through
  // the geometry collapse. Result: indexed mesh with clean smooth shading.
  // ============================================================
  const CHIBI = {
    positions_b64: "",
    colors_b64:    "",
    normals_b64:   "",
    indices_b64:   "",
    index_dtype:   "uint16",
    pos_min:       [-0.3853718566855948, 0.0, -0.3638252670307321],
    pos_scale:     [0.7707437133711896, 1.7, 0.7276505340614642],
    // Sims-style floating diamond icons (circular photo PNGs with alpha)
    zach_icon_png_b64:  "",
    jason_icon_png_b64: "",
  };

  // ============================================================
  // EMBEDDED MESHY CHARACTER MODELS
  // Converted from OBJ/MTL/PNG into compact typed-array payloads so each
  // selectable professor can use their real textured Meshy model without
  // adding OBJLoader/MTLLoader or external asset files. To add the next
  // character, create another key in MESHY_MODELS with the same fields and
  // set modelAsset on that character below.
  // ============================================================
    // ============================================================
  // EMBEDDED MESHY CHARACTER MODELS
  // Full OBJ topology is quantized into base64 buffers; PNG textures are resized
  // to 1024px so the whole game remains a single self-contained HTML file.
  // Player assets use rotationY: Math.PI because this game treats group-local
  // -Z as the professor's forward direction. Dean Jason uses +Z forward.
  // ============================================================
  // MESHY_MODELS is now split into assets/models/*.asset.js for GitHub Pages.
// Jason is loaded up-front so Dean Jason stays 3D; selected instructor models load on demand.

  function decodeBase64ToBytes(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }


  function imageMimeFromBase64(b64) {
    if (!b64) return 'image/png';
    if (b64.startsWith('/9j/')) return 'image/jpeg';
    if (b64.startsWith('iVBOR')) return 'image/png';
    if (b64.startsWith('UklGR')) return 'image/webp';
    return 'image/png';
  }

  function dataUrlFromBase64Image(b64) {
    return 'data:' + imageMimeFromBase64(b64) + ';base64,' + b64;
  }

  function buildChibiMesh() {
    const posBytes  = decodeBase64ToBytes(CHIBI.positions_b64);
    const colBytes  = decodeBase64ToBytes(CHIBI.colors_b64);
    const normBytes = decodeBase64ToBytes(CHIBI.normals_b64);
    const idxBytes  = decodeBase64ToBytes(CHIBI.indices_b64);

    const posQuant = new Uint16Array(posBytes.buffer, posBytes.byteOffset, posBytes.byteLength / 2);
    const colors   = new Uint8Array(colBytes.buffer, colBytes.byteOffset, colBytes.byteLength);
    const normsQuant = new Int8Array(normBytes.buffer, normBytes.byteOffset, normBytes.byteLength);
    let indices;
    if (CHIBI.index_dtype === 'uint16') {
      indices = new Uint16Array(idxBytes.buffer, idxBytes.byteOffset, idxBytes.byteLength / 2);
    } else {
      indices = new Uint32Array(idxBytes.buffer, idxBytes.byteOffset, idxBytes.byteLength / 4);
    }

    // Dequantize positions
    const n = posQuant.length / 3;
    const positions = new Float32Array(n * 3);
    const [pmx, pmy, pmz] = CHIBI.pos_min;
    const [psx, psy, psz] = CHIBI.pos_scale;
    for (let i = 0; i < n; i++) {
      positions[i*3+0] = posQuant[i*3+0] / 65535 * psx + pmx;
      positions[i*3+1] = posQuant[i*3+1] / 65535 * psy + pmy;
      positions[i*3+2] = posQuant[i*3+2] / 65535 * psz + pmz;
    }
    // Dequantize normals
    const normals = new Float32Array(normsQuant.length);
    for (let i = 0; i < normsQuant.length; i++) normals[i] = normsQuant[i] / 127;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color',    new THREE.BufferAttribute(colors, 3, true));
    geo.setAttribute('normal',   new THREE.BufferAttribute(normals, 3));
    geo.setIndex(new THREE.BufferAttribute(indices, 1));
    geo.computeBoundingSphere();

    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    return new THREE.Mesh(geo, mat);
  }

  function makeEmbeddedPngTexture(b64, mime) {
    const img = new Image();
    img.src = mime ? ('data:' + mime + ';base64,' + b64) : dataUrlFromBase64Image(b64);
    const t = new THREE.Texture(img);
    t.magFilter = THREE.LinearFilter;
    t.minFilter = THREE.LinearMipMapLinearFilter;
    t.generateMipmaps = true;
    t.anisotropy = 4;
    if ('encoding' in t) t.encoding = THREE.sRGBEncoding;
    img.onload = () => { t.needsUpdate = true; };
    return t;
  }

  function buildEmbeddedMeshyBody(asset) {
    const posBytes  = decodeBase64ToBytes(asset.positions_b64);
    const uvBytes   = decodeBase64ToBytes(asset.uvs_b64);
    const normBytes = decodeBase64ToBytes(asset.normals_b64);
    const idxBytes  = decodeBase64ToBytes(asset.indices_b64);

    const posQuant  = new Uint16Array(posBytes.buffer, posBytes.byteOffset, posBytes.byteLength / 2);
    const uvQuant   = new Uint16Array(uvBytes.buffer, uvBytes.byteOffset, uvBytes.byteLength / 2);
    const normQuant = new Int8Array(normBytes.buffer, normBytes.byteOffset, normBytes.byteLength);
    let indices;
    if (asset.index_dtype === 'uint16') {
      indices = new Uint16Array(idxBytes.buffer, idxBytes.byteOffset, idxBytes.byteLength / 2);
    } else {
      indices = new Uint32Array(idxBytes.buffer, idxBytes.byteOffset, idxBytes.byteLength / 4);
    }

    const n = posQuant.length / 3;
    const positions = new Float32Array(n * 3);
    const uvs = new Float32Array(n * 2);
    const normals = new Float32Array(n * 3);
    const [pmx, pmy, pmz] = asset.pos_min;
    const [psx, psy, psz] = asset.pos_scale;
    for (let i = 0; i < n; i++) {
      positions[i*3+0] = posQuant[i*3+0] / 65535 * psx + pmx;
      positions[i*3+1] = posQuant[i*3+1] / 65535 * psy + pmy;
      positions[i*3+2] = posQuant[i*3+2] / 65535 * psz + pmz;
      normals[i*3+0] = normQuant[i*3+0] / 127;
      normals[i*3+1] = normQuant[i*3+1] / 127;
      normals[i*3+2] = normQuant[i*3+2] / 127;
      uvs[i*2+0] = uvQuant[i*2+0] / 65535;
      uvs[i*2+1] = uvQuant[i*2+1] / 65535;
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('normal',   new THREE.BufferAttribute(normals, 3));
    geo.setAttribute('uv',       new THREE.BufferAttribute(uvs, 2));
    geo.setIndex(new THREE.BufferAttribute(indices, 1));
    geo.computeBoundingSphere();

    const tex = makeEmbeddedPngTexture(asset.texture_b64 || asset.texture_png_b64, asset.texture_mime);
    const mat = new THREE.MeshLambertMaterial({
      map: tex,
      side: THREE.DoubleSide,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.y = asset.rotationY || 0;

    const body = new THREE.Group();
    body.name = 'meshy-body-' + (asset.label || 'character');
    body.add(mesh);
    return body;
  }

  const playerGroup = new THREE.Group();
  const playerBodyRoot = new THREE.Group();
  playerGroup.add(playerBodyRoot);

  const defaultPlayerBody = new THREE.Group();
  const chibi = buildChibiMesh();
  // The exported mesh: feet at y=0, faces +Z. We'll put it in a group so we can rotate.
  // Chibi default orientation: positive Z is "out of the body's front". We want forward = -Z, so rotate 180.
  chibi.rotation.y = Math.PI;
  defaultPlayerBody.add(chibi);
  playerBodyRoot.add(defaultPlayerBody);
  const cachedMeshyBodies = {};

  // GitHub Pages split-build model loader. Keeps every file below GitHub's
  // browser upload limit and loads only the selected instructor mesh on demand.
  const MESHY_ASSET_FILES = {
    "zach": "./assets/models/zach.asset.js",
    "kretz": "./assets/models/kretz.asset.js",
    "stutting": "./assets/models/stutting.asset.js",
    "biscobing": "./assets/models/biscobing.asset.js",
    "hallas": "./assets/models/hallas.asset.js",
    "dominic": "./assets/models/dominic.asset.js",
    "clay": "./assets/models/clay.asset.js",
    "jj": "./assets/models/jj.asset.js",
    "jason": "./assets/models/jason.asset.js"
};
  const _meshyAssetPromises = {};
  function loadMeshyAssetScript(assetId) {
    if (!assetId) return Promise.resolve(null);
    if (typeof MESHY_MODELS !== 'undefined' && MESHY_MODELS && MESHY_MODELS[assetId]) {
      return Promise.resolve(MESHY_MODELS[assetId]);
    }
    if (_meshyAssetPromises[assetId]) return _meshyAssetPromises[assetId];
    const src = MESHY_ASSET_FILES[assetId];
    if (!src) return Promise.resolve(null);
    _meshyAssetPromises[assetId] = new Promise(resolve => {
      const s = document.createElement('script');
      s.src = src;
      s.async = true;
      s.onload = () => resolve((typeof MESHY_MODELS !== 'undefined' && MESHY_MODELS) ? MESHY_MODELS[assetId] : null);
      s.onerror = () => {
        console.warn('Could not load Meshy asset:', assetId, src);
        resolve(null);
      };
      document.head.appendChild(s);
    });
    return _meshyAssetPromises[assetId];
  }


  // ============================================================
  // CHARACTER AVATAR ACCENTS — DISABLED
  //
  // Tried building per-character chibi variants by overlaying colored boxes
  // (hair cap, shirt, tie, beard, glasses, hat) on top of the shared chibi
  // mesh. Result looked like a tan box stacked on the head — additive
  // overlays don't override the baked-in colors of the source mesh.
  //
  // Doing this properly would require rebuilding the chibi data per
  // character (8x larger payload, ~2.5MB), which isn't worth it for a
  // single-file HTML game. Instead each character is identified by:
  //   • their unique floating diamond photo (Zach's photo for Zach, etc.)
  //   • their name in the HUD ("PROF. KRETZSCHMAR" etc.)
  //   • their unique perk (faster throw, more ammo, etc.)
  //   • their card on the select screen
  //
  // If you want to revive the overlay attempt later, the look data is still
  // on each character object — just uncomment applyAvatarLook below and the
  // accent meshes will rebuild. The look attributes (hairColor, beard,
  // shirtColor, etc.) are documented above in the CHARACTERS array.
  // ============================================================
  const avatarAccents = new THREE.Group();
  defaultPlayerBody.add(avatarAccents);
  function applyAvatarLook(look) {
    // Intentional no-op. See note above.
    while (avatarAccents.children.length > 0) {
      const c = avatarAccents.children[0];
      avatarAccents.remove(c);
    }
  }

  // ============================================================
  // SIMS-STYLE FLOATING DIAMOND
  // A diamond-shaped (rotated square) plane that hovers above a character,
  // displays their photo icon, and gently bobs + spins. Each character gets
  // their own diamond, color-tinted by their role (player = NTC gold,
  // dean = red danger).
  // ============================================================

  // ============================================================
  // PROFILE PHOTOS — from uploaded Profiles.zip
  // These normalized 256x256 circular PNGs drive both the character-select
  // card portraits and the floating Sims-style diamonds above characters.
  // ClayProfile.png has now been added too, so every selectable instructor
  // has a matching card portrait and floating diamond photo.
  // ============================================================
  const PROFILE_IMAGES = {
    zach: "",
    dominic: "",
    kretz: "",
    stutting: "",
    biscobing: "",
    hallas: "",
    clay: "",
    jj: "",
    jason: "",
  };

  function makeIconTexture(b64) {
    const img = new Image();
    img.src = dataUrlFromBase64Image(b64);
    const t = new THREE.Texture(img);
    t.magFilter = THREE.LinearFilter;
    t.minFilter = THREE.LinearMipMapLinearFilter;
    t.generateMipmaps = true;
    t.anisotropy = 4;
    if ('encoding' in t) t.encoding = THREE.sRGBEncoding;
    img.onload = () => { t.needsUpdate = true; };
    return t;
  }

  function buildSimsDiamond(iconB64, frameColor = 0xe8b830) {
    const group = new THREE.Group();

    // Outer diamond "frame" — a square rotated 45° on its Z axis so it looks
    // like a diamond. Two thin slabs colored gold or red.
    const frameOuter = new THREE.Mesh(
      new THREE.BoxGeometry(0.48, 0.48, 0.06),
      lambert(frameColor)
    );
    frameOuter.rotation.z = Math.PI / 4;
    group.add(frameOuter);
    // Slightly smaller inner frame for depth
    const frameInner = new THREE.Mesh(
      new THREE.BoxGeometry(0.40, 0.40, 0.065),
      lambert(0x0e1a3c)   // NTC dark navy backing
    );
    frameInner.rotation.z = Math.PI / 4;
    group.add(frameInner);

    // The actual photo icon — flat plane in front of the frame.
    const iconTex = makeIconTexture(iconB64);
    const iconMat = new THREE.MeshBasicMaterial({
      map: iconTex,
      transparent: true,
      alphaTest: 0.1,
      depthWrite: false,
      toneMapped: false,
    });
    const icon = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.34), iconMat);
    icon.position.z = 0.045;       // just in front of the frame
    icon.renderOrder = 12;
    group.add(icon);
    // Mirror on the back so it's visible from behind too (no rotating fix needed)
    const iconBack = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.34), iconMat);
    iconBack.position.z = -0.045;
    iconBack.rotation.y = Math.PI;
    iconBack.renderOrder = 12;
    group.add(iconBack);

    group.userData.bobSeed = Math.random() * Math.PI * 2;
    return group;
  }

  // Build the player's diamond (Zach's photo, gold frame) and attach to playerGroup.
  const playerDiamond = buildSimsDiamond(PROFILE_IMAGES.zach || CHIBI.zach_icon_png_b64, 0xe8b830);
  playerDiamond.position.y = 2.20;   // just above the chibi's head (chibi tops out ~1.7)
  playerGroup.add(playerDiamond);


  // Small backpack on the chibi's back. Group-local +Z is the chibi's BACK
  // (chibi mesh is rotated π so its local +Z front becomes group -Z).
  {
    const pack = new THREE.Mesh(
      new THREE.BoxGeometry(0.32, 0.36, 0.14),
      lambert(0x6a3a1a)
    );
    pack.position.set(0, 1.15, 0.26);
    // top flap accent
    const flap = new THREE.Mesh(
      new THREE.BoxGeometry(0.30, 0.08, 0.02),
      lambert(0x8a4a20)
    );
    flap.position.set(0, 1.27, 0.34);
    // straps over shoulders — narrow & dark, only on the back side
    const strapMat = lambert(0x3a1a08);
    const strapL = new THREE.Mesh(
      new THREE.BoxGeometry(0.04, 0.30, 0.025),
      strapMat
    );
    const strapR = strapL.clone();
    strapL.position.set(-0.10, 1.13, 0.18);
    strapR.position.set( 0.10, 1.13, 0.18);
    defaultPlayerBody.add(pack);
    defaultPlayerBody.add(flap);
    defaultPlayerBody.add(strapL);
    defaultPlayerBody.add(strapR);
  }

  function getCachedMeshyBody(assetId) {
    const asset = MESHY_MODELS && MESHY_MODELS[assetId];
    if (!asset) return null;
    if (!cachedMeshyBodies[assetId]) {
      cachedMeshyBodies[assetId] = buildEmbeddedMeshyBody(asset);
    }
    return cachedMeshyBodies[assetId];
  }

  function setPlayerBodyForCharacter(ch) {
    while (playerBodyRoot.children.length > 0) {
      playerBodyRoot.remove(playerBodyRoot.children[0]);
    }

    const assetId = ch && ch.modelAsset;
    const asset = assetId ? MESHY_MODELS[assetId] : null;
    const body = asset ? getCachedMeshyBody(assetId) : null;
    if (body) {
      playerBodyRoot.add(body);
      if (playerDiamond) {
        playerDiamond.userData.baseY = asset.diamondY || 2.20;
        playerDiamond.position.y = playerDiamond.userData.baseY;
      }
    } else {
      playerBodyRoot.add(defaultPlayerBody);
      if (playerDiamond) {
        playerDiamond.userData.baseY = 2.20;
        playerDiamond.position.y = 2.20;
      }
    }
  }

  playerGroup.position.set(0, 0, 2.5);
  scene.add(playerGroup);

  const player = {
    pos: new THREE.Vector3(0, 0, 2.5),
    vel: new THREE.Vector3(),
    facing: 0,             // yaw radians
    targetFacing: 0,
    radius: 0.35,
    walkBob: 0,
    speed: 4.0,
    sprintSpeed: 7.2,
    isMoving: false,
    isSprinting: false,
  };

  // ============================================================
  // DEAN JASON — the antagonist
  //
  // Procedurally built blocky figure (taller than the chibi). He patrols the
  // north corridor — back and forth between two waypoints — with a forward
  // vision cone. If Prof. Thunder enters the cone with clear line-of-sight,
  // the dean ALERTS: vision cone flashes red, an alert timer counts down, and
  // if the player doesn't break sight before it expires → BUSTED.
  // ============================================================
  function buildDean() {
    const embeddedJason = (typeof MESHY_MODELS !== 'undefined') ? MESHY_MODELS.jason : null;
    if (embeddedJason) {
      const body = buildEmbeddedMeshyBody(embeddedJason);
      body.name = 'dean-jason-meshy';
      return body;
    }

    // Dean Jason — based on the new photo:
    //   - Fuller, rounder face (not stern/square)
    //   - Brown hair (medium-dark, parted)
    //   - Full graying beard
    //   - No glasses
    //   - Light-colored checkered sweater over white shirt
    //   - Carries a clipboard (his badge of authority)
    const g = new THREE.Group();
    const skinMat    = lambert(0xe8c0a0);      // warm complexion
    const skinShade  = lambert(0xc89878);
    const pantsMat   = lambert(0x2a2818);      // khaki/dark slacks
    const pantsDark  = lambert(0x1a1810);
    const shirtMat   = lambert(0xf5f0e8);      // off-white inner shirt
    const sweaterTan = lambert(0xc8b08a);      // tan / warm beige sweater base
    const sweaterDk  = lambert(0x6a4828);      // checker accent
    const shoeMat    = lambert(0x2a1a08);      // brown shoes
    const hairMat    = lambert(0x3a2818);      // dark brown hair
    const beardMat   = lambert(0x707068);      // graying beard
    const beardDark  = lambert(0x4a3838);      // mustache / darker beard zones

    // Legs (khaki)
    const legL = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.92, 0.22), pantsMat);
    legL.position.set(-0.12, 0.50, 0);
    g.add(legL);
    const legR = legL.clone(); legR.position.x = 0.12; g.add(legR);
    // Shoes (brown)
    const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.08, 0.30), shoeMat);
    shoeL.position.set(-0.12, 0.04, 0.04); g.add(shoeL);
    const shoeR = shoeL.clone(); shoeR.position.x = 0.12; g.add(shoeR);

    // Torso — checkered sweater (round and a bit thick like the photo)
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.78, 0.34), sweaterTan);
    torso.position.set(0, 1.36, 0); g.add(torso);
    // Sweater checker pattern — alternating dark squares
    // 4 rows × 4 cols of tiny accent panels on the front
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        if ((row + col) % 2 === 0) continue; // checkered: skip half
        const sq = new THREE.Mesh(
          new THREE.BoxGeometry(0.12, 0.18, 0.005),
          sweaterDk
        );
        sq.position.set(-0.21 + col*0.14, 1.05 + row*0.18, 0.171);
        g.add(sq);
      }
    }
    // White shirt collar V at the neck — visible above the sweater
    const collar = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.10, 0.04), shirtMat);
    collar.position.set(0, 1.72, 0.18); g.add(collar);

    // Arms (sweater)
    const armL = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.70, 0.20), sweaterTan);
    armL.position.set(-0.34, 1.30, 0); g.add(armL);
    const armR = armL.clone(); armR.position.x = 0.34; g.add(armR);
    // Sweater pattern on arm (one stripe each)
    for (const arm of [-0.34, 0.34]) {
      const sleeveCheck = new THREE.Mesh(new THREE.BoxGeometry(0.165, 0.14, 0.205), sweaterDk);
      sleeveCheck.position.set(arm, 1.45, 0); g.add(sleeveCheck);
    }
    // Hands
    const handL = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.10, 0.12), skinMat);
    handL.position.set(-0.34, 0.93, 0); g.add(handL);
    const handR = handL.clone(); handR.position.x = 0.34; g.add(handR);

    // Neck
    const neck = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.10, 0.15), skinMat);
    neck.position.set(0, 1.78, 0); g.add(neck);

    // Head — bigger, rounder
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.42, 0.34), skinMat);
    head.position.set(0, 2.04, 0); g.add(head);

    // Brown hair — top + sides, slightly thicker than before
    const hairTop = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.10, 0.36), hairMat);
    hairTop.position.set(0, 2.28, -0.02); g.add(hairTop);
    const hairBack = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.18, 0.04), hairMat);
    hairBack.position.set(0, 2.12, -0.17); g.add(hairBack);
    const hairSideL = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.20, 0.32), hairMat);
    hairSideL.position.set(-0.175, 2.06, 0); g.add(hairSideL);
    const hairSideR = hairSideL.clone(); hairSideR.position.x = 0.175; g.add(hairSideR);
    // Hair-part shadow on forehead
    const hairForehead = new THREE.Mesh(new THREE.BoxGeometry(0.30, 0.04, 0.04), hairMat);
    hairForehead.position.set(0.04, 2.18, 0.16); g.add(hairForehead);

    // EYES — small dark blocks, NO glasses
    const eyeL = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.01), lambert(0x1a1010));
    eyeL.position.set(-0.07, 2.08, 0.171); g.add(eyeL);
    const eyeR = eyeL.clone(); eyeR.position.x = 0.07; g.add(eyeR);

    // FULL GRAYING BEARD — wraps from sideburns around the chin to the other
    // sideburn, with a moustache strip across the upper lip.
    // Cheek beard (sides of face)
    const beardSideL = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.18, 0.20), beardMat);
    beardSideL.position.set(-0.155, 1.96, 0.05); g.add(beardSideL);
    const beardSideR = beardSideL.clone(); beardSideR.position.x = 0.155; g.add(beardSideR);
    // Chin beard — main mass, extends down below the head
    const beardChin = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.22, 0.16), beardMat);
    beardChin.position.set(0, 1.85, 0.10); g.add(beardChin);
    // Beard front (fuller volume in front)
    const beardFront = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.16, 0.04), beardDark);
    beardFront.position.set(0, 1.86, 0.20); g.add(beardFront);
    // Moustache — thin horizontal block above the mouth area
    const moustache = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.04, 0.04), beardDark);
    moustache.position.set(0, 1.98, 0.18); g.add(moustache);

    // Smile-ish neutral mouth (peeking through beard) — slight curve via
    // angled tiny block
    const mouth = new THREE.Mesh(new THREE.BoxGeometry(0.10, 0.02, 0.01), lambert(0x402020));
    mouth.position.set(0, 1.93, 0.20); g.add(mouth);

    // Clipboard tucked under right arm — his badge of authority (kept)
    const clipBoard = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.30, 0.025), lambert(0x402a18));
    clipBoard.position.set(0.40, 1.20, 0.08); g.add(clipBoard);
    const clipPaper = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.24, 0.005), lambert(0xefefef));
    clipPaper.position.set(0.40, 1.20, 0.10); g.add(clipPaper);
    const clipClasp = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.03, 0.02), lambert(0xa0a0a0));
    clipClasp.position.set(0.40, 1.32, 0.10); g.add(clipClasp);
    return g;
  }

  // Vision cone visual — a flat fan on the floor in front of the dean.
  function buildVisionCone(rangeUnits, halfAngle) {
    const segs = 18;
    const positions = [0, 0.01, 0];  // apex slightly above floor
    for (let i = 0; i <= segs; i++) {
      const a = -halfAngle + (i / segs) * (halfAngle * 2);
      positions.push(Math.sin(a) * rangeUnits, 0.01, Math.cos(a) * rangeUnits);
    }
    const indices = [];
    for (let i = 1; i <= segs; i++) indices.push(0, i, i + 1);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setIndex(indices);
    const mat = new THREE.MeshBasicMaterial({
      color: 0xfff04a,
      transparent: true,
      opacity: 0.22,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    return new THREE.Mesh(geo, mat);
  }

  const DEAN_VISION_RANGE = 9.0;
  const DEAN_VISION_HALF  = Math.PI / 4.5; // ~40° each side = 80° total cone
  const DEAN_PATROL_SPEED = 1.6;
  const DEAN_CHASE_SPEED  = 4.6;            // faster than walk, slower than sprint — sprint to escape!
  const DEAN_SUSPICIOUS_SPEED = 2.6;        // moves toward last-known position to investigate
  const DEAN_ALERT_TIME   = 0.9;            // seconds in sight (continuous) before BUSTED
  const DEAN_LOSE_INTEREST_TIME = 5.0;      // seconds out of sight before he gives up chase
  const DEAN_PAUSE_AT_WAYPOINT = 1.2;

  const dean = {
    group: null,
    visionCone: null,
    // Start FAR from the player — patrolling the south corridor by default,
    // so the player can leave the lobby safely and then has to evade once
    // the dean's patrol brings him near.
    pos: new THREE.Vector3(0, 0, 13),
    facing: 0,                                 // facing +Z (away from lobby)
    targetFacing: 0,
    // Default patrol: walks the south corridor between near-lobby and the dead end.
    patrolPath: [
      new THREE.Vector3(0, 0, 7),   // near south side of lobby
      new THREE.Vector3(0, 0, 20),  // near south dead-end (Timberwolf Pride poster)
    ],
    patrolIdx: 1,
    pauseTimer: 0,
    state: 'patrol',          // 'patrol' | 'paused' | 'suspicious' | 'chase' | 'caught'
    alertLevel: 0,             // 0..1 — fills while in sight
    radius: 0.45,
    walkBob: 0,
    // Chase mechanics
    lastKnownPlayerPos: null,  // Vector3 (last spot we saw the player)
    timeOutOfSight: 0,         // seconds since we last spotted the player while chasing
    // Spoken line on screen
    barkText: '',
    barkTimer: 0,
  };
  dean.group = buildDean();
  dean.group.position.copy(dean.pos);
  dean.group.rotation.y = dean.facing;
  scene.add(dean.group);
  dean.visionCone = buildVisionCone(DEAN_VISION_RANGE, DEAN_VISION_HALF);
  scene.add(dean.visionCone);
  // Floating diamond above the dean — Jason's photo, red danger frame
  dean.diamond = buildSimsDiamond(PROFILE_IMAGES.jason || CHIBI.jason_icon_png_b64, 0xd83a3a);
  dean.diamond.position.y = 2.65;   // just above dean's head (dean is taller than chibi)
  dean.group.add(dean.diamond);

