  // Currently selected character — set by clicking a card. Defaults to first.
  let selectedCharacter = CHARACTERS[0];

  function getInstructorName() {
    return (selectedCharacter && selectedCharacter.name) ? selectedCharacter.name : 'your instructor';
  }

  function getInstructorTitle() {
    return selectedCharacter ? ('Professor ' + getInstructorName()) : 'your instructor';
  }

  function getInstructorLastName() {
    if (!selectedCharacter || !selectedCharacter.name) return 'INSTRUCTOR';
    const parts = selectedCharacter.name.trim().split(/\s+/);
    return parts[parts.length - 1] || 'INSTRUCTOR';
  }

