  // Currently-active goal (set by chooseGoal())
  let currentGoal = GOAL_ROOMS[0];

  // Holds the meshes added when the goal is chosen, so we can remove them between runs.
  const goalMeshes = [];

  function clearGoalMeshes() {
    for (const m of goalMeshes) scene.remove(m);
    goalMeshes.length = 0;
  }

  function buildPlaque(goal) {
    const plaqueTex = makeCanvasTexture(256, (gx, s) => {
      gx.fillStyle = '#1a2c5e'; gx.fillRect(0,0,s,s);
      gx.strokeStyle = '#e8b830'; gx.lineWidth = 4;
      gx.strokeRect(s*0.06, s*0.06, s*0.88, s*0.88);
      gx.fillStyle = '#e8b830';
      gx.textAlign = 'center'; gx.textBaseline = 'middle';
      gx.font = 'bold italic 88px Georgia, serif';
      gx.fillText(goal.displayName, s/2, s*0.40);
      gx.fillStyle = '#f0f0e8';
      const plaqueSubtitle = goal.subtitle.replace(/^NTC INSTRUCTOR/, 'PROF. ' + getInstructorLastName().toUpperCase());
      gx.font = plaqueSubtitle.length > 27 ? 'bold 14px monospace' : (plaqueSubtitle.length > 23 ? 'bold 16px monospace' : 'bold 19px monospace');
      gx.fillText(plaqueSubtitle, s/2, s*0.72);
      gx.font = '16px monospace';
      gx.fillText('9:00 AM', s/2, s*0.86);
    });
    const plaque = new THREE.Mesh(
      new THREE.PlaneGeometry(1.4, 0.55),
      new THREE.MeshBasicMaterial({ map: plaqueTex })
    );
    plaque.position.set(goal.plaque.x, goal.plaque.y, goal.plaque.z);
    plaque.rotation.y = goal.plaque.rotY;
    scene.add(plaque);
    goalMeshes.push(plaque);
  }

  // Apply the selected character's perk to ammo / player / dean parameters.
  // Always start from defaults — every call fully resets, so swapping
  // characters between runs is idempotent.
  const PERK_DEFAULTS = {
    starterAmmo: 3,       // base count if no starter perk
    throwCooldownMs: 350, // base throw cooldown
    sprintSpeed: 7.2,     // base player.sprintSpeed
    visionConePreview: 0, // base extra preview range (no preview)
  };
  function applyCharacterPerks(ch) {
    // Reset to base values
    player.sprintSpeed = PERK_DEFAULTS.sprintSpeed;
    player.throwCooldownMs = PERK_DEFAULTS.throwCooldownMs;
    player.visionConePreview = PERK_DEFAULTS.visionConePreview;
    let starter = PERK_DEFAULTS.starterAmmo;

    if (!ch) ch = CHARACTERS[0];
    switch (ch.perkType) {
      case 'starter_ammo':
        starter = ch.perkValue;
        break;
      case 'fast_throw':
        player.throwCooldownMs = ch.perkValue;
        break;
      case 'fast_sprint':
        player.sprintSpeed = ch.perkValue;
        break;
      case 'long_sight':
        player.visionConePreview = ch.perkValue;
        break;
    }
    // Fill starter ammo with a variety of types
    for (let i = 0; i < starter; i++) {
      ammo.stack.push(PAPERWORK_TYPES[i % PAPERWORK_TYPES.length]);
    }
  }

  // Replace the photo inside the floating player diamond. The diamond was
  // built with two icon planes (front + back) — both share a single material,
  // so we just need to update the texture's image source.
  function swapPlayerDiamondPhoto(b64OrNull, urlOrNull) {
    if (!playerDiamond) return;
    const src = urlOrNull
      ? urlOrNull
      : (b64OrNull ? dataUrlFromBase64Image(b64OrNull) : null);
    if (!src) return;
    playerDiamond.traverse(obj => {
      if (obj.isMesh && obj.material && obj.material.map &&
          obj.material.map.image && obj.material.map.image.tagName === 'IMG') {
        const img = obj.material.map.image;
        img.onload = () => { obj.material.map.needsUpdate = true; };
        img.src = src;
      }
    });
  }

  function chooseGoal() {
    clearTrail();
    clearGoalMeshes();
    currentGoal = GOAL_ROOMS[Math.floor(Math.random() * GOAL_ROOMS.length)];
    buildTrail(currentGoal.trail);
    buildPlaque(currentGoal);
    // Reset ammo + respawn pickups for the fresh run
    ammo.stack = [];
    ammo.lastThrowTime = 0;
    // ─── Apply selected character's perks ───
    applyCharacterPerks(selectedCharacter);
    // Clear any in-flight projectiles too
    for (const p of projectiles) scene.remove(p.group);
    projectiles.length = 0;
    spawnAllPickups();
    refreshAmmoHud();
    // Swap the actual playable body when a real embedded Meshy model exists.
    setPlayerBodyForCharacter(selectedCharacter);
    // Swap the floating diamond's photo to match the chosen character
    swapPlayerDiamondPhoto(selectedCharacter.portrait_b64, selectedCharacter.portrait_url);
    // Rebuild the chibi's accent overlays (hair color, shirt, beard, glasses, etc.)
    // to match the chosen character.
    applyAvatarLook(selectedCharacter.look);
    // Update both HUD labels that mention the goal room
    if (hudObjectiveTextEl) {
      hudObjectiveTextEl.innerHTML = `Get to <b>${currentGoal.displayName}</b> before 9:00 AM`;
    }
    const hudInfoRoom = document.getElementById('hud-info-room');
    if (hudInfoRoom) hudInfoRoom.textContent = currentGoal.displayName;
    // Update the "PROF. THUNDER" label to show the chosen prof's last name
    const hudInfoLabel = document.querySelector('.hud-info .label');
    if (hudInfoLabel) {
      hudInfoLabel.textContent = '▸ PROF. ' + getInstructorLastName().toUpperCase();
    }
  }

  // ============================================================
  // NAVIGATION GRAPH
  // The building has a small set of "junctions" (lobby center, doorways into
  // corridors, deep ends). The dean and any AI can route through them rather
  // than trying to walk through walls. Each node lists its neighbors as
  // line-of-sight-clear waypoints.
  // ============================================================

  // The building has a small set of "junctions" (lobby center, doorways into
  // corridors, deep ends). The dean and any AI can route through them rather
  // than trying to walk through walls. Each node lists its neighbors as
  // line-of-sight-clear waypoints.
  // ============================================================
  const navNodes = [
    /* 0 */ new THREE.Vector3(0,   0,  0),    // lobby center
    /* 1 */ new THREE.Vector3(0,   0, -6),    // lobby ↔ north corridor doorway
    /* 2 */ new THREE.Vector3(0,   0, -13),   // mid north corridor
    /* 3 */ new THREE.Vector3(-4,  0, -18),   // north corridor ↔ ROOM 217 door
    /* 4 */ new THREE.Vector3(-9,  0, -18),   // inside ROOM 217 (target!)
    /* 5 */ new THREE.Vector3( 4,  0, -18),   // north corridor ↔ comp lab door
    /* 6 */ new THREE.Vector3(0,   0, -20),   // north corridor dead end
    /* 7 */ new THREE.Vector3(0,   0,  6),    // lobby ↔ south corridor doorway
    /* 8 */ new THREE.Vector3(0,   0, 13),    // mid south corridor
    /* 9 */ new THREE.Vector3(-4,  0, 18),    // south corridor ↔ cafeteria door
    /* 10*/ new THREE.Vector3( 4,  0, 18),    // south corridor ↔ faculty lounge door
    /* 11*/ new THREE.Vector3(0,   0, 20),    // south corridor dead end (timberwolf pride)
  ];
  // Adjacency list — index pairs that are "connected" with a clear line in the building
  const navEdges = [
    [0,1],[0,7],                  // lobby ↔ corridors
    [1,2],[2,3],[2,5],[2,6],      // north corridor
    [3,4],                        // into ROOM 217
    [7,8],[8,9],[8,10],[8,11],    // south corridor
  ];
  const navAdj = navNodes.map(() => []);
  for (const [a,b] of navEdges) { navAdj[a].push(b); navAdj[b].push(a); }

  // Find the nearest nav node to a world point.
  function nearestNavNode(pos) {
    let bestIdx = 0, bestD = Infinity;
    for (let i = 0; i < navNodes.length; i++) {
      const dx = pos.x - navNodes[i].x, dz = pos.z - navNodes[i].z;
      const d = dx*dx + dz*dz;
      if (d < bestD) { bestD = d; bestIdx = i; }
    }
    return bestIdx;
  }

  // BFS shortest path through nav graph. Returns array of Vector3 waypoints,
  // INCLUDING the goal position appended at the end so you walk into the room.
  function pathTo(fromPos, toPos) {
    const a = nearestNavNode(fromPos);
    const b = nearestNavNode(toPos);
    if (a === b) return [navNodes[b].clone(), toPos.clone()];
    const prev = new Array(navNodes.length).fill(-1);
    const visited = new Array(navNodes.length).fill(false);
    const queue = [a]; visited[a] = true;
    while (queue.length) {
      const u = queue.shift();
      if (u === b) break;
      for (const v of navAdj[u]) {
        if (!visited[v]) { visited[v] = true; prev[v] = u; queue.push(v); }
      }
    }
    if (!visited[b]) return [toPos.clone()];  // disconnected; fall back to direct
    const path = [];
    let cur = b;
    while (cur !== a) { path.push(navNodes[cur].clone()); cur = prev[cur]; }
    path.reverse();
    path.push(toPos.clone());
    return path;
  }

  // Test if a sight line from `from` to `to` is unblocked by any wall.
  // Uses the existing wall-AABB list with a slab raycast.
  function clearLineOfSight(from, to) {
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const dist = Math.hypot(dx, dz);
    if (dist < 0.001) return true;
    const dirX = dx / dist, dirZ = dz / dist;
    for (const w of walls) {
      let tmin = -Infinity, tmax = Infinity;
      // x slab
      if (Math.abs(dirX) < 1e-6) {
        if (from.x < w.minX || from.x > w.maxX) continue;
      } else {
        let t1 = (w.minX - from.x) / dirX;
        let t2 = (w.maxX - from.x) / dirX;
        if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) continue;
      }
      // z slab
      if (Math.abs(dirZ) < 1e-6) {
        if (from.z < w.minZ || from.z > w.maxZ) continue;
      } else {
        let t1 = (w.minZ - from.z) / dirZ;
        let t2 = (w.maxZ - from.z) / dirZ;
        if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) continue;
      }
      // a wall blocks if it intersects within the segment
      if (tmin > 0.05 && tmin < dist - 0.05) return false;
    }
    return true;
  }

  // Pick a movement target along the dean's current path. He follows a queue
  // of waypoints; once close to one, drops it and steers toward the next.
  let _deanPath = [];
  function setDeanPath(targetPos) {
    _deanPath = pathTo(dean.pos, targetPos);
  }
  function followPath(dt, speed) {
    // Skip waypoints that we're already very close to (smooth corner cutting).
    while (_deanPath.length > 0) {
      const wp = _deanPath[0];
      const dx = wp.x - dean.pos.x, dz = wp.z - dean.pos.z;
      const d = Math.hypot(dx, dz);
      if (d < 0.5) { _deanPath.shift(); continue; }
      // Move toward this waypoint
      const ux = dx / d, uz = dz / d;
      dean.pos.x += ux * speed * dt;
      dean.pos.z += uz * speed * dt;
      dean.targetFacing = Math.atan2(ux, uz);
      dean.walkBob += dt * (speed > 3 ? 12 : 7);
      return true; // still moving
    }
    return false; // arrived
  }

  function deanBark(text, duration=2.5) {
    dean.barkText = text;
    dean.barkTimer = duration;
    if (deanBarkEl) {
      deanBarkEl.textContent = '“' + text + '”';
      deanBarkEl.classList.add('show');
    }
  }

  function updateDean(dt) {
    if (gameState !== 'playing') return;

    // ----- STUNNED state: dean is frozen reading paperwork -----
    // While stunned: he can't see, can't move, can't catch. Vision cone
    // is dimmed. The stun tick decrements; on expiry, returns to patrol.
    if (dean.state === 'stunned') {
      dean.stunTimer -= dt;
      // Dim/blue cone for stunned state
      dean.visionCone.material.color.setHex(0x3060c0);
      dean.visionCone.material.opacity = 0.08;
      // Slight wobble for visual interest
      dean.group.rotation.x = 0.45 + Math.sin(performance.now() * 0.012) * 0.04;
      // HUD warning off
      hudWarningEl.classList.remove('show');
      if (dean.stunTimer <= 0) {
        dean.state = 'patrol';
        dean.group.rotation.x = 0;
      }
      // Tick bark timer here too
      if (dean.barkTimer > 0) {
        dean.barkTimer -= dt;
        if (dean.barkTimer <= 0 && deanBarkEl) deanBarkEl.classList.remove('show');
      }
      return;   // skip all detection / movement / collision while stunned
    }

    // ----- Detection check FIRST (drives state machine) -----
    const toPlayer = new THREE.Vector3(
      player.pos.x - dean.pos.x, 0, player.pos.z - dean.pos.z
    );
    const distToPlayer = toPlayer.length();

    // Walking up to the dean = instant detection. He doesn't need to see you
    // if you literally bump into him.
    if (distToPlayer < 1.2) {
      // Immediate BUSTED regardless of state.
      if (dean.state !== 'chase') {
        deanBark(pickBark('spotted'));
        playStinger('spotted');
      }
      dean.state = 'chase';
      triggerBusted();
      return;
    }

    let inSight = false;
    if (distToPlayer < DEAN_VISION_RANGE && distToPlayer > 0.01) {
      const angleToPlayer = Math.atan2(toPlayer.x, toPlayer.z);
      let dAng = angleToPlayer - dean.facing;
      while (dAng > Math.PI) dAng -= Math.PI*2;
      while (dAng < -Math.PI) dAng += Math.PI*2;
      // Wider effective vision when CHASING — he's actively scanning
      const halfFov = (dean.state === 'chase') ? DEAN_VISION_HALF * 1.4 : DEAN_VISION_HALF;
      if (Math.abs(dAng) < halfFov && clearLineOfSight(dean.pos, player.pos)) {
        inSight = true;
      }
    }
    // PERIPHERAL VISION: if the player is close (within 3.5m) and there's clear
    // line of sight, the dean notices even if they're behind him. This keeps
    // the game fair — you can't just walk up to the dean from behind for free.
    if (!inSight && distToPlayer < 3.5 && clearLineOfSight(dean.pos, player.pos)) {
      inSight = true;
    }
    // Player sprinting at close range = audible = "seen"
    if (!inSight && distToPlayer < 5.5 && player.isSprinting &&
        clearLineOfSight(dean.pos, player.pos)) {
      inSight = true;
    }

    // ----- State transitions -----
    if (inSight) {
      // remember where we saw him
      dean.lastKnownPlayerPos = player.pos.clone();
      dean.timeOutOfSight = 0;

      if (dean.state === 'patrol' || dean.state === 'paused' || dean.state === 'suspicious') {
        // Just spotted him! Switch to chase.
        if (dean.state !== 'chase') {
          deanBark(pickBark('spotted'));
          playStinger('spotted');
        }
        dean.state = 'chase';
        setDeanPath(dean.lastKnownPlayerPos);
      } else if (dean.state === 'chase') {
        // Continuously re-target as we keep seeing him
        setDeanPath(dean.lastKnownPlayerPos);
      }
      // Alert level fills while in sight + chasing
      dean.alertLevel = Math.min(1.0, dean.alertLevel + dt / DEAN_ALERT_TIME);
    } else {
      // Out of sight
      if (dean.state === 'chase') {
        dean.timeOutOfSight += dt;
        // Keep going to last known position
        if (_deanPath.length === 0 && dean.lastKnownPlayerPos) {
          setDeanPath(dean.lastKnownPlayerPos);
        }
        if (dean.timeOutOfSight > DEAN_LOSE_INTEREST_TIME) {
          // Give up and return to patrol
          deanBark(pickBark('giveup'));
          dean.state = 'patrol';
          dean.timeOutOfSight = 0;
          dean.alertLevel = 0;
          _deanPath = [];
        }
      } else if (dean.state === 'suspicious') {
        // walk toward last-known position; once arrived, go back to patrol
        if (_deanPath.length === 0) {
          dean.state = 'patrol';
        }
      }
      // Alert decays slowly
      dean.alertLevel = Math.max(0, dean.alertLevel - dt * 0.6);
    }

    // ----- Movement per state -----
    if (dean.state === 'patrol') {
      // If we have no path, head to next patrol waypoint
      if (_deanPath.length === 0) {
        _deanPath = [dean.patrolPath[dean.patrolIdx].clone()];
      }
      const moving = followPath(dt, DEAN_PATROL_SPEED);
      if (!moving) {
        // Arrived → pause briefly, advance patrol index
        dean.state = 'paused';
        dean.pauseTimer = DEAN_PAUSE_AT_WAYPOINT;
        dean.patrolIdx = (dean.patrolIdx + 1) % dean.patrolPath.length;
      }
    } else if (dean.state === 'paused') {
      dean.pauseTimer -= dt;
      // Sweep gaze
      const sweep = Math.sin(dean.pauseTimer * 4.0) * 0.5;
      const next = dean.patrolPath[dean.patrolIdx];
      dean.targetFacing = Math.atan2(next.x - dean.pos.x, next.z - dean.pos.z) + sweep;
      if (dean.pauseTimer <= 0) dean.state = 'patrol';
    } else if (dean.state === 'chase') {
      followPath(dt, DEAN_CHASE_SPEED);
    } else if (dean.state === 'suspicious') {
      followPath(dt, DEAN_SUSPICIOUS_SPEED);
    }

    // ----- Smooth-rotate to targetFacing -----
    let dFace = dean.targetFacing - dean.facing;
    while (dFace > Math.PI) dFace -= Math.PI*2;
    while (dFace < -Math.PI) dFace += Math.PI*2;
    dean.facing += dFace * Math.min(1, 6 * dt);

    // ----- Apply transforms -----
    const moving = dean.state === 'patrol' || dean.state === 'chase' || dean.state === 'suspicious';
    const bobY = moving ? Math.abs(Math.sin(dean.walkBob)) * 0.04 : 0;
    dean.group.position.set(dean.pos.x, bobY, dean.pos.z);
    dean.group.rotation.y = dean.facing;
    dean.visionCone.position.set(dean.pos.x, 0, dean.pos.z);
    dean.visionCone.rotation.y = dean.facing;

    // ----- Vision cone color/opacity reflects state -----
    if (dean.state === 'chase') {
      dean.visionCone.material.color.setHex(0xff2020);
      dean.visionCone.material.opacity = 0.40;
    } else if (dean.alertLevel > 0.2) {
      // Player was almost spotted — orange warning cone
      dean.visionCone.material.color.setHex(0xff8020);
      dean.visionCone.material.opacity = 0.32;
    } else if (dean.state === 'suspicious') {
      dean.visionCone.material.color.setHex(0xffc040);
      dean.visionCone.material.opacity = 0.25;
    } else {
      dean.visionCone.material.color.setHex(0xfff04a);
      // long_sight perk: make the patrol cone more visible (easier to plan around)
      dean.visionCone.material.opacity = 0.18 + (player.visionConePreview ? 0.18 : 0);
    }

    // ----- HUD warning shows when alert level is rising -----
    if (dean.alertLevel > 0.15) {
      hudWarningEl.classList.add('show');
      hudWarningEl.textContent = dean.state === 'chase' ? '⚠ DEAN IS CHASING YOU' : '⚠ DEAN SUSPECTS YOU';
    } else {
      hudWarningEl.classList.remove('show');
    }

    // ----- BUSTED check: dean is physically near you while chasing -----
    // Use a generous catch range — anywhere inside ~1 unit of his body during
    // chase is "the dean has grabbed Professor Thunder by the lapels".
    if (distToPlayer < 1.0 && dean.state === 'chase') {
      triggerBusted();
      return;
    }

    // ----- Dean's body as a soft collider for the player -----
    if (dean.state !== 'caught') {
      const sep = new THREE.Vector3(player.pos.x - dean.pos.x, 0, player.pos.z - dean.pos.z);
      const sepLen = sep.length();
      const minDist = dean.radius + player.radius + 0.05;
      if (sepLen < minDist && sepLen > 0.001) {
        sep.divideScalar(sepLen);
        const push = minDist - sepLen;
        player.pos.x += sep.x * push;
        player.pos.z += sep.z * push;
      }
    }

    // SECOND busted check, post-push, in case ordering matters
    const finalDx = player.pos.x - dean.pos.x;
    const finalDz = player.pos.z - dean.pos.z;
    if (Math.hypot(finalDx, finalDz) < 1.0 && dean.state === 'chase') {
      triggerBusted();
      return;
    }

    // ----- Bark timer -----
    if (dean.barkTimer > 0) {
      dean.barkTimer -= dt;
      if (dean.barkTimer <= 0 && deanBarkEl) deanBarkEl.classList.remove('show');
    }
  }

  // Variety of one-liners. Picked randomly.
  function pickBark(kind) {
    const lastName = getInstructorLastName();
    const lines = {
      spotted: [
        `PROFESSOR ${lastName.toUpperCase()}! HALT!`,
        `There you are, ${lastName}! Why aren't you in class?!`,
        "STOP RIGHT THERE!",
        `I've been looking for you, ${lastName}!`,
        "Get back here, professor!",
      ],
      giveup: [
        "...where did they go?",
        "Probably hiding in the lounge again.",
        "I'll catch them next time.",
        "Hmm. Lost them.",
      ],
    };
    const arr = lines[kind] || ['...'];
    return arr[Math.floor(Math.random() * arr.length)];
  }

  // ============================================================
  // PAPERWORK COMBAT — Prof. Thunder's only defense against the Dean.
  //
  // Pickups: physical paperwork stacks scattered through the building.
  // Walking near one adds 1 to your ammo stack. Each one is a different
  // type of bureaucratic nonsense (Workday request, course extension form,
  // student complaint, etc) — purely cosmetic; gameplay-wise they all stun.
  //
  // Throw: SPACE launches the top paper from your stack forward at high
  // speed. If it hits the Dean, he STUNS for 2 seconds:
  //   - vision cone goes blue & dim (can't see)
  //   - he stops moving and bows forward "reading"
  //   - chase state resets to patrol after stun
  //
  // The throw mechanic is the *only* way to recover from being spotted
  // mid-corridor. Use your ammo wisely.
  // ============================================================
  const PAPERWORK_TYPES = [
    { id: 'workday',    icon: '📋', name: 'Workday Request',         color: 0xf5f0d8, lines: ['Approved by', 'Submit Date', 'Cost Center'] },
    { id: 'complaint',  icon: '😤', name: 'Student Complaint',       color: 0xf3d6d6, lines: ['Dear Dean,', 'I would like to', 'unacceptable.'] },
    { id: 'extension',  icon: '⏰', name: 'Course Extension Form',   color: 0xd8e8f3, lines: ['Extension Req.', 'Additional Weeks', 'Reason: snow'] },
    { id: 'addDrop',    icon: '📝', name: 'Late Add/Drop Petition',  color: 0xf3e8c8, lines: ['Add: CS-201', 'Drop: MATH-150', 'Week: 3'] },
    { id: 'tenure',     icon: '📚', name: 'Tenure Documentation',    color: 0xefefef, lines: ['Service:', 'Scholarship:', 'Teaching:'] },
    { id: 'syllabus',   icon: '📖', name: 'Updated Syllabus',        color: 0xe8e0f0, lines: ['Week 1:', 'Week 2:', 'Office hrs:'] },
    { id: 'workorder',  icon: '🔧', name: 'IT Ticket #4729',         color: 0xd8f0d8, lines: ['Printer not', 'working again.', 'Priority: low'] },
  ];

  // ----- Player ammo state -----
  const ammo = {
    stack: [],         // array of PAPERWORK_TYPES entries
    lastThrowTime: 0,
  };

  // ----- HUD refs (declared later, so cache lazily) -----
  let _ammoHudCache = null;
  function getAmmoHud() {
    if (_ammoHudCache) return _ammoHudCache;
    _ammoHudCache = {
      bar:    document.getElementById('hud-ammo'),
      icon:   document.getElementById('ammo-icon'),
      num:    document.getElementById('ammo-num'),
      label:  document.getElementById('ammo-label'),
      pickup: document.getElementById('hud-pickup'),
    };
    return _ammoHudCache;
  }
  function refreshAmmoHud() {
    const h = getAmmoHud();
    if (!h.bar) return;
    const top = ammo.stack[ammo.stack.length - 1];
    if (top) {
      h.bar.classList.remove('empty');
      h.icon.textContent  = top.icon;
      h.num.textContent   = ammo.stack.length;
      h.label.textContent = top.name;
    } else {
      h.bar.classList.add('empty');
      h.icon.textContent  = '📋';
      h.num.textContent   = '0';
      h.label.textContent = 'NO PAPERWORK';
    }
  }
  let _pickupHideTimer = 0;
  function showPickupToast(type) {
    const h = getAmmoHud();
    if (!h.pickup) return;
    h.pickup.textContent = `+1 ${type.name.toUpperCase()}  ${type.icon}`;
    h.pickup.classList.add('show');
    h.bar.classList.add('flash');
    clearTimeout(_pickupHideTimer);
    _pickupHideTimer = setTimeout(() => {
      h.pickup.classList.remove('show');
      h.bar.classList.remove('flash');
    }, 1600);
  }

  // ----- Paperwork stack pickups (3D objects in the world) -----
  // Each pickup is a small leaning stack of papers; when player gets close,
  // adds 1-3 sheets of that paperwork type to the inventory.
  const paperPickups = [];   // {group, pos, type, value, taken}

  function makePaperStackMesh(type, sheets = 3) {
    const g = new THREE.Group();
    const matPaper = lambert(type.color);
    for (let i = 0; i < sheets; i++) {
      const sheet = new THREE.Mesh(
        new THREE.BoxGeometry(0.32, 0.012, 0.42),
        matPaper
      );
      sheet.position.y = 0.012 + i * 0.014;
      sheet.rotation.y = (Math.random() - 0.5) * 0.20;
      sheet.position.x = (Math.random() - 0.5) * 0.03;
      sheet.position.z = (Math.random() - 0.5) * 0.03;
      g.add(sheet);
    }
    // Tiny letter accents on top sheet
    const stamp = new THREE.Mesh(
      new THREE.BoxGeometry(0.04, 0.005, 0.04),
      lambert(0xa01818)   // red stamp
    );
    stamp.position.set(0.10, 0.012 + sheets * 0.014 + 0.005, 0.15);
    g.add(stamp);
    // Pulse marker — small upright glowing rectangle so it's visible across the room
    const beacon = new THREE.Mesh(
      new THREE.BoxGeometry(0.08, 0.50, 0.005),
      new THREE.MeshBasicMaterial({ color: 0xe8b830 })
    );
    beacon.position.set(0, 0.30, 0);
    beacon.userData.isPickupBeacon = true;
    g.add(beacon);
    // Floating tiny icon emoji via canvas texture
    const iconTex = (() => {
      const c = document.createElement('canvas');
      c.width = c.height = 64;
      const ctx = c.getContext('2d');
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(type.icon, 32, 36);
      const t = new THREE.CanvasTexture(c);
      t.magFilter = THREE.LinearFilter;
      return t;
    })();
    const iconPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(0.28, 0.28),
      new THREE.MeshBasicMaterial({ map: iconTex, transparent: true, alphaTest: 0.1, depthWrite: false })
    );
    iconPlane.position.set(0, 0.65, 0);
    iconPlane.userData.isPickupIcon = true;
    g.add(iconPlane);
    return g;
  }

  function spawnPickup(x, z, type, value = 2) {
    const group = makePaperStackMesh(type, Math.min(5, value + 1));
    group.position.set(x, 0, z);
    scene.add(group);
    paperPickups.push({ group, pos: new THREE.Vector3(x, 0, z), type, value, taken: false });
  }

  // Pickup locations — distributed through the building so player has reason
  // to detour for ammo. Each pickup gives 1-3 papers.
  // Coordinates picked to be safe spots (not buried in walls/doorways).
  function spawnAllPickups() {
    // Clear any prior pickups (e.g. on restart)
    for (const p of paperPickups) scene.remove(p.group);
    paperPickups.length = 0;
    const T = PAPERWORK_TYPES;
    // Lobby — friendly starter cache near the welcome desk
    spawnPickup(-4.8,  0.5, T[0], 2);   // Workday near desk
    // North corridor stops
    spawnPickup(-2.0, -10.0, T[1], 2);   // Student complaint
    spawnPickup( 2.0, -13.5, T[2], 2);   // Course extension
    spawnPickup(-1.8, -19.5, T[3], 2);   // Late add/drop near end of corridor
    // South corridor stops
    spawnPickup( 1.8,   9.0, T[4], 2);   // Tenure paperwork
    spawnPickup(-2.0,  15.0, T[5], 2);   // Updated syllabus
    spawnPickup( 2.0,  19.5, T[6], 2);   // IT ticket near south dead-end
    // Inside computer lab (worth detour)
    spawnPickup( 8.0, -19.0, T[0], 3);   // 3-pack Workday
    spawnPickup( 12.0,-16.0, T[2], 2);
    // Inside cafeteria (worth detour)
    spawnPickup(-8.0,  16.0, T[1], 2);
    spawnPickup(-11.0, 19.5, T[3], 3);   // 3-pack add/drop
    // Faculty lounge (most ammo — incentive to risk it)
    spawnPickup( 8.0,  16.0, T[4], 3);
    spawnPickup( 12.0, 19.5, T[5], 2);
    // Classroom A (room 217)
    spawnPickup(-11.0,-16.0, T[6], 2);
    spawnPickup(-8.0, -20.0, T[2], 2);
  }

  // ----- Pickup proximity check (runs each frame) -----
  function updatePickups(dt) {
    if (gameState !== 'playing') return;
    // Animate beacons + icons (pulse + bob)
    const tt = performance.now() * 0.003;
    for (const p of paperPickups) {
      if (p.taken) continue;
      // Bob the icon
      for (const child of p.group.children) {
        if (child.userData.isPickupIcon) {
          child.position.y = 0.65 + Math.sin(tt + p.pos.x + p.pos.z) * 0.06;
          // Billboard toward camera
          child.lookAt(camera.position.x, child.position.y + p.group.position.y, camera.position.z);
        }
        if (child.userData.isPickupBeacon) {
          const pulse = 0.6 + 0.4 * Math.sin(tt * 1.6 + p.pos.x);
          child.scale.set(pulse, 1, 1);
        }
      }
      // Pickup check (generous radius — easy to grab while moving)
      const dx = player.pos.x - p.pos.x;
      const dz = player.pos.z - p.pos.z;
      if (dx*dx + dz*dz < 1.4 * 1.4) {
        // Take it
        p.taken = true;
        scene.remove(p.group);
        for (let i = 0; i < p.value; i++) ammo.stack.push(p.type);
        showPickupToast(p.type);
        refreshAmmoHud();
        playPickupSound();
      }
    }
  }

  function playPickupSound() {
    if (!audioCtx) return;
    const t = audioCtx.currentTime;
    const o = audioCtx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(880, t);
    o.frequency.linearRampToValueAtTime(1320, t + 0.10);
    const g = audioCtx.createGain();
    g.gain.setValueAtTime(0.10, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    o.connect(g); g.connect(masterGain);
    o.start(t); o.stop(t + 0.20);
  }
  function playThrowSound() {
    if (!audioCtx) return;
    const t = audioCtx.currentTime;
    // "whoosh" — short pink-noise burst
    const buf = audioCtx.createBuffer(1, 0.12 * audioCtx.sampleRate, audioCtx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) {
      data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
    }
    const src = audioCtx.createBufferSource(); src.buffer = buf;
    const hp = audioCtx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 1200;
    const g = audioCtx.createGain(); g.gain.value = 0.12;
    src.connect(hp); hp.connect(g); g.connect(masterGain);
    src.start(t); src.stop(t + 0.13);
  }
  function playStunSound() {
    if (!audioCtx) return;
    const t = audioCtx.currentTime;
    // "Bonk!" — low square pulse
    const o = audioCtx.createOscillator();
    o.type = 'square';
    o.frequency.setValueAtTime(180, t);
    o.frequency.exponentialRampToValueAtTime(60, t + 0.18);
    const g = audioCtx.createGain();
    g.gain.setValueAtTime(0.18, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.30);
    o.connect(g); g.connect(masterGain);
    o.start(t); o.stop(t + 0.32);
  }

  // ----- Projectiles -----
  // Each projectile flies in a straight line for ~3 seconds or until hitting
  // the dean / a wall.
  const projectiles = [];
  const PROJ_SPEED = 12.0;
  const PROJ_LIFE  = 2.0;     // seconds before despawn
  const STUN_DURATION = 2.0;  // seconds the dean is frozen on hit

  function spawnProjectile(type) {
    const group = new THREE.Group();
    const sheet = new THREE.Mesh(
      new THREE.BoxGeometry(0.30, 0.01, 0.42),
      lambert(type.color)
    );
    group.add(sheet);
    // Red stamp accent on top
    const stamp = new THREE.Mesh(
      new THREE.BoxGeometry(0.05, 0.012, 0.05),
      lambert(0xa01818)
    );
    stamp.position.set(0.10, 0.008, 0.15);
    group.add(stamp);

    // Spawn slightly in front of player, at chest height
    const dirX = -Math.sin(player.facing);
    const dirZ = -Math.cos(player.facing);
    group.position.set(
      player.pos.x + dirX * 0.5,
      1.30,
      player.pos.z + dirZ * 0.5
    );
    // Initial yaw matches throw direction
    group.rotation.y = player.facing;
    scene.add(group);
    projectiles.push({
      group,
      dir: new THREE.Vector3(dirX, 0, dirZ),
      life: PROJ_LIFE,
      type,
      spinSpeed: (Math.random() - 0.5) * 14 + 8,
    });
  }

  function tryThrow() {
    if (gameState !== 'playing') return;
    if (ammo.stack.length === 0) return;
    const now = performance.now();
    if (now - ammo.lastThrowTime < (player.throwCooldownMs || 350)) return;  // throttle
    ammo.lastThrowTime = now;
    const type = ammo.stack.pop();
    spawnProjectile(type);
    refreshAmmoHud();
    playThrowSound();
  }

  function updateProjectiles(dt) {
    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      // Move forward
      p.group.position.x += p.dir.x * PROJ_SPEED * dt;
      p.group.position.z += p.dir.z * PROJ_SPEED * dt;
      // Spin around its forward axis for that "tumbling paper" feel
      p.group.rotation.z += p.spinSpeed * dt;
      p.group.rotation.x += p.spinSpeed * 0.6 * dt;
      p.life -= dt;
      // Wall collision
      let hitWall = false;
      for (const w of walls) {
        if (p.group.position.x > w.minX - 0.05 && p.group.position.x < w.maxX + 0.05 &&
            p.group.position.z > w.minZ - 0.05 && p.group.position.z < w.maxZ + 0.05) {
          hitWall = true; break;
        }
      }
      // Dean hit?
      const ddx = p.group.position.x - dean.pos.x;
      const ddz = p.group.position.z - dean.pos.z;
      const ddh = p.group.position.y - 1.8;   // dean's torso/head zone
      if (ddx*ddx + ddz*ddz < 0.55*0.55 && Math.abs(ddh) < 1.2) {
        // BONK
        stunDean(p.type);
        scene.remove(p.group);
        projectiles.splice(i, 1);
        continue;
      }
      if (hitWall || p.life <= 0) {
        scene.remove(p.group);
        projectiles.splice(i, 1);
      }
    }
  }

  // ----- Dean stun -----
  function stunDean(type) {
    dean.state = 'stunned';
    dean.stunTimer = STUN_DURATION;
    // Reset chase tracking when stunned — clean slate after
    dean.alertLevel = 0;
    dean.timeOutOfSight = 0;
    dean.lastKnownPlayerPos = null;
    _deanPath = [];
    // Slump animation: small forward lean. Cleanest way is to tilt the whole
    // group's rotation.x for the duration.
    dean.group.rotation.x = 0.45;
    // Speech bubble — react to the specific paperwork type
    deanBark(pickStunBark(type));
    playStunSound();
  }

  function pickStunBark(type) {
    const lines = {
      workday:   ['I haven\'t approved that yet!', 'Submit it through Workday!', 'CC HR next time!'],
      complaint: ['Another one?!', 'Forward to your dean...', 'Have you tried mediation?'],
      extension: ['Form C-217 is the WRONG form!', 'Talk to the registrar!', 'This needs a signature!'],
      addDrop:   ['Week 3 is the DEADLINE!', 'You missed late-add!', 'See your advisor!'],
      tenure:    ['Where\'s your service record?!', 'You\'re three years behind!', 'I need page 12 too!'],
      syllabus:  ['Page numbers are MISSING!', 'Where\'s the rubric?!', 'Outcomes need ALIGNMENT!'],
      workorder: ['IT will get to it eventually...', 'That printer is leased!', 'Submit by 4PM!'],
    };
    const arr = lines[type.id] || ['...'];
    return arr[Math.floor(Math.random() * arr.length)];
  }

  // ============================================================
  // CAMERA RIG (third-person)
  // ============================================================
  const camRig = {
    yaw: 0,
    pitch: -0.08,         // almost horizontal — eye-level over the shoulder
    distance: 3.0,        // closer to player
    height: 0.6,          // camera not much above player head
    pos: new THREE.Vector3(),
    target: new THREE.Vector3(),
    bob: 0,
  };

  // ============================================================
  // INPUT
  // ============================================================
  const keys = {};

  window.addEventListener('keydown', e => {
    if (e.code === 'Escape') {
      if (gameState === 'playing') pauseGame();
      else if (gameState === 'paused') resumeGame();
      return;
    }
    // SPACE throws paperwork (one throw per press — not auto-repeat)
    if (e.code === 'Space' && !e.repeat) {
      tryThrow();
    }
    keys[e.code] = true;
    // prevent arrow keys / space from scrolling the page
    if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE'].includes(e.code)) {
      e.preventDefault();
    }
  });
  window.addEventListener('keyup', e => {
    keys[e.code] = false;
  });
  // make canvas focusable so it gets keyboard events on the artifact page
  canvas.setAttribute('tabindex', '0');
  canvas.addEventListener('click', () => { canvas.focus(); });

  // ============================================================
  // COLLISION
  // ============================================================
  function resolveCollisions(pos, radius) {
    for (const w of walls) {
      // closest point on AABB to pos
      const cx = Math.max(w.minX, Math.min(pos.x, w.maxX));
      const cz = Math.max(w.minZ, Math.min(pos.z, w.maxZ));
      const dx = pos.x - cx;
      const dz = pos.z - cz;
      const dist2 = dx*dx + dz*dz;
      if (dist2 < radius*radius && dist2 > 0.0001) {
        const dist = Math.sqrt(dist2);
        const push = (radius - dist);
        pos.x += (dx / dist) * push;
        pos.z += (dz / dist) * push;
      } else if (dist2 <= 0.0001) {
        // inside AABB — push out shortest axis
        const dxL = pos.x - w.minX, dxR = w.maxX - pos.x;
        const dzT = pos.z - w.minZ, dzB = w.maxZ - pos.z;
        const m = Math.min(dxL, dxR, dzT, dzB);
        if (m === dxL) pos.x = w.minX - radius - 0.01;
        else if (m === dxR) pos.x = w.maxX + radius + 0.01;
        else if (m === dzT) pos.z = w.minZ - radius - 0.01;
        else pos.z = w.maxZ + radius + 0.01;
      }
    }
  }

  // Ray cast from player to camera target to prevent clipping
  function rayWallHit(origin, dir, maxDist) {
    let closest = maxDist;
    for (const w of walls) {
      // slab method
      let tmin = -Infinity, tmax = Infinity;
      for (let axis = 0; axis < 2; axis++) {
        const o = axis === 0 ? origin.x : origin.z;
        const d = axis === 0 ? dir.x : dir.z;
        const lo = axis === 0 ? w.minX : w.minZ;
        const hi = axis === 0 ? w.maxX : w.maxZ;
        if (Math.abs(d) < 1e-6) {
          if (o < lo || o > hi) { tmin = Infinity; break; }
        } else {
          let t1 = (lo - o) / d;
          let t2 = (hi - o) / d;
          if (t1 > t2) { const t = t1; t1 = t2; t2 = t; }
          tmin = Math.max(tmin, t1);
          tmax = Math.min(tmax, t2);
          if (tmin > tmax) break;
        }
      }
      if (tmin > 0 && tmin < closest && tmin < tmax) {
        closest = tmin;
      }
    }
    return closest;
  }

  // ============================================================
  // AUDIO (synthesized)
  // ============================================================
  let audioCtx = null;
  let masterGain = null;
  let fluorescentHum = null;

  function initAudio() {
    if (audioCtx) return;
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = 0.5;
    masterGain.connect(audioCtx.destination);

    // Fluorescent hum: 120 Hz low + slight 60Hz mod
    const osc = audioCtx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = 120;
    const lp = audioCtx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 200;
    const g = audioCtx.createGain();
    g.gain.value = 0.012;
    osc.connect(lp); lp.connect(g); g.connect(masterGain);
    osc.start();
    fluorescentHum = g;
  }
  function playFootstep() {
    if (!audioCtx) return;
    const t = audioCtx.currentTime;
    const noise = audioCtx.createBufferSource();
    const buf = audioCtx.createBuffer(1, 0.06 * audioCtx.sampleRate, audioCtx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) {
      data[i] = (Math.random()*2 - 1) * (1 - i/data.length);
    }
    noise.buffer = buf;
    const bp = audioCtx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 800 + Math.random()*400;
    bp.Q.value = 1.0;
    const g = audioCtx.createGain();
    g.gain.setValueAtTime(0.12, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    noise.connect(bp); bp.connect(g); g.connect(masterGain);
    noise.start(t);
    noise.stop(t + 0.07);
  }
  let lastStep = 0;
  function maybeStep(dt) {
    if (!player.isMoving) return;
    const stepInterval = player.isSprinting ? 0.30 : 0.45;
    lastStep += dt;
    if (lastStep >= stepInterval) {
      playFootstep();
      lastStep = 0;
    }
  }

  // Short musical sting on game-state change.
  function playStinger(kind) {
    if (!audioCtx) return;
    const t = audioCtx.currentTime;
    let notes;
    if (kind === 'busted') {
      notes = [[330, 0], [311, 0.12], [294, 0.24], [277, 0.36], [220, 0.55]]; // descending wail
    } else if (kind === 'late') {
      notes = [[440, 0], [415, 0.15], [392, 0.30]];
    } else if (kind === 'spotted') {
      notes = [[523, 0], [523, 0.10], [523, 0.20]]; // 3 sharp blasts
    } else { // 'win'
      notes = [[392, 0], [494, 0.10], [587, 0.20], [784, 0.35]]; // triumphant fanfare
    }
    for (const [hz, ot] of notes) {
      const o = audioCtx.createOscillator();
      o.type = kind === 'win' ? 'sawtooth' : 'square';
      o.frequency.value = hz;
      const g = audioCtx.createGain();
      const tg = t + ot;
      g.gain.setValueAtTime(0.0001, tg);
      g.gain.exponentialRampToValueAtTime(0.18, tg + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, tg + 0.5);
      o.connect(g); g.connect(masterGain);
      o.start(tg);
      o.stop(tg + 0.55);
    }
  }

  // ============================================================
  // HUD
  // ============================================================
  const hudRoomEl = document.getElementById('hud-room');
  const hudTimeEl = document.getElementById('hud-time');
  const hudToastEl = document.getElementById('hud-toast');
  const hudWarningEl = document.getElementById('hud-warning');
  const deanBarkEl = document.getElementById('hud-dean-bark');
  const hudObjectiveTextEl = document.getElementById('hud-objective-text');
  let currentRoom = "";
  let toastTimer = 0;

  function updateRoom() {
    let r = "";
    for (const t of roomTriggers) {
      if (player.pos.x >= t.minX && player.pos.x <= t.maxX &&
          player.pos.z >= t.minZ && player.pos.z <= t.maxZ) {
        r = t.name;
        break;
      }
    }
    if (r && r !== currentRoom) {
      currentRoom = r;
      hudRoomEl.textContent = r;
      showToast("ENTERED " + r);
    }
  }
  function showToast(txt) {
    hudToastEl.textContent = txt;
    hudToastEl.classList.add('show');
    toastTimer = 2.0;
  }

  // In-game clock — starts at 8:52 AM, 1 real second = 6 in-game seconds
  let gameMinutes = 8 * 60 + 52;
  function updateClock(dt) {
    gameMinutes += dt * 6.0 / 60.0; // 1 real second = 0.1 in-game minutes? actually scale up:
  }
  // Easier: 1 minute real time = 1 hour in game. So 1 real second = 1 in-game minute.
  function updateClockFmt() {
    let mins = Math.floor(gameMinutes) % (24*60);
    const h24 = Math.floor(mins / 60);
    const m = mins % 60;
    const am = h24 < 12;
    const h12 = ((h24 + 11) % 12) + 1;
    const mm = m.toString().padStart(2,'0');
    // Time remaining until 9:00 in seconds (real-time scale: 0.11 in-game min per real sec)
    const inGameMinsLeft = Math.max(0, (9 * 60) - gameMinutes);
    const realSecsLeft = inGameMinsLeft / 0.11;
    const danger = realSecsLeft < 18;
    const veryDanger = realSecsLeft < 8;
    hudTimeEl.innerHTML = '<span class="small">BELL RINGS AT 9:00 AM</span><br>' +
      `${h12}:${mm} ${am ? 'AM' : 'PM'}`;
    // Visual cues — re-style border on tightening time
    hudTimeEl.style.borderColor =
      veryDanger ? '#ff2020' : (danger ? '#ff8020' : '');
    hudTimeEl.style.color =
      veryDanger ? '#ff5050' : (danger ? '#ffa050' : '');
    hudTimeEl.style.textShadow =
      veryDanger ? '0 0 10px #ff2020' : (danger ? '0 0 8px #ff8020' : '');
  }

  // ============================================================
  // GAME STATE
  // ============================================================
  let gameState = 'title'; // 'title' | 'loading' | 'playing' | 'paused' | 'busted' | 'late' | 'won'
  var titleEl = document.getElementById('title-screen');
  var loadingEl = document.getElementById('loading');
  var hudEl = document.getElementById('hud');
  var pauseEl = document.getElementById('pause-screen');
  var bustedEl = document.getElementById('busted-screen');
  var lateEl = document.getElementById('late-screen');
  var winEl = document.getElementById('win-screen');

  // The title start button is handled by the lightweight bootstrap in index.html.
  // Do not attach a second handler here, because it can fire before the game is fully initialized on slow GitHub Pages loads.
  document.getElementById('resume-btn').addEventListener('click', resumeGame);
  document.getElementById('title-btn').addEventListener('click', goToTitle);
  document.getElementById('restart-btn').addEventListener('click', restartGame);
  document.getElementById('busted-retry').addEventListener('click', restartGame);
  document.getElementById('late-retry').addEventListener('click', restartGame);
  document.getElementById('win-retry').addEventListener('click', restartGame);

  // ─── Character select screen ────────────────────────────────
  var charSelectEl = document.getElementById('char-select-screen');
  var csGridEl     = document.getElementById('cs-grid');
  var csBackBtn    = document.getElementById('cs-back-btn');
  var csPlayBtn    = document.getElementById('cs-play-btn');
  let _csSelectedId  = null;

  function ensureUiRefs() {
    titleEl = titleEl || document.getElementById('title-screen');
    loadingEl = loadingEl || document.getElementById('loading');
    hudEl = hudEl || document.getElementById('hud');
    pauseEl = pauseEl || document.getElementById('pause-screen');
    bustedEl = bustedEl || document.getElementById('busted-screen');
    lateEl = lateEl || document.getElementById('late-screen');
    winEl = winEl || document.getElementById('win-screen');
    charSelectEl = charSelectEl || document.getElementById('char-select-screen');
    csGridEl = csGridEl || document.getElementById('cs-grid');
    csBackBtn = csBackBtn || document.getElementById('cs-back-btn');
    csPlayBtn = csPlayBtn || document.getElementById('cs-play-btn');
  }

  // Build the selected character model during the roster screen when the browser
  // has a spare moment. This makes the Play button feel much faster without
  // changing gameplay or removing the single-file setup.
  let _prewarmToken = 0;
  function scheduleSelectedModelPrewarm(ch) {
    const assetId = ch && ch.modelAsset;
    if (!assetId || cachedMeshyBodies[assetId]) return;
    const token = ++_prewarmToken;
    const runner = () => {
      loadMeshyAssetScript(assetId).then(() => {
        if (token !== _prewarmToken || cachedMeshyBodies[assetId]) return;
        try { getCachedMeshyBody(assetId); }
        catch (err) { console.warn('Model prewarm skipped:', assetId, err); }
      });
    };
    if ('requestIdleCallback' in window) {
      window.requestIdleCallback(runner, { timeout: 900 });
    } else {
      setTimeout(runner, 120);
    }
  }


  function buildCharacterCards() {
    ensureUiRefs();
    csGridEl.innerHTML = '';
    for (const ch of CHARACTERS) {
      const card = document.createElement('div');
      card.className = 'cs-card';
      card.dataset.id = ch.id;
      // Portrait source: explicit URL overrides base64; falls back to placeholder
      const portraitSrc = ch.portrait_url
        ? ch.portrait_url
        : dataUrlFromBase64Image(ch.portrait_b64);
      const modelBadge = ch.modelAsset ? '<div class="cs-role">REAL 3D MESH AVAILABLE</div>' : '';
      card.innerHTML =
        '<div class="cs-portrait"><img src="' + portraitSrc + '" alt="' + ch.name + '"></div>' +
        '<div class="cs-name">' + ch.name + '</div>' +
        '<div class="cs-role">' + ch.role + '</div>' +
        modelBadge +
        '<div class="cs-perk">' + ch.perk + '</div>';
      card.addEventListener('click', () => selectCard(ch.id));
      csGridEl.appendChild(card);
    }
  }
  function selectCard(id) {
    ensureUiRefs();
    _csSelectedId = id;
    selectedCharacter = CHARACTERS.find(c => c.id === id) || CHARACTERS[0];
    // Highlight the chosen card
    for (const node of csGridEl.children) {
      node.classList.toggle('selected', node.dataset.id === id);
    }
    csPlayBtn.disabled = false;
    csPlayBtn.textContent = '▶ Sneak To Class As ' + selectedCharacter.name.split(' ')[0].toUpperCase();
    scheduleSelectedModelPrewarm(selectedCharacter);
  }

  function showCharacterSelect() {
    ensureUiRefs();
    if (titleEl) titleEl.style.display = 'none';
    if (!csGridEl.children.length) buildCharacterCards();
    if (charSelectEl) charSelectEl.classList.add('show');
    // Default to first character so the Play button can light up if user just hits it
    selectCard(selectedCharacter.id);
  }
  function hideCharacterSelect() {
    ensureUiRefs();
    if (charSelectEl) charSelectEl.classList.remove('show');
  }

  if (csBackBtn) csBackBtn.addEventListener('click', () => {
    hideCharacterSelect();
    if (titleEl) titleEl.style.display = '';
  });
  if (csPlayBtn) csPlayBtn.addEventListener('click', () => {
    hideCharacterSelect();
    startGame();
  });

  function resetGameState() {
    // Reset player
    player.pos.set(0, 0, 2.5);
    player.vel.set(0,0,0);
    player.facing = 0;
    player.targetFacing = 0;
    // Reset dean: starts in south corridor (far from player), patrolling.
    dean.pos.set(0, 0, 13);
    dean.facing = 0;
    dean.targetFacing = 0;
    dean.patrolIdx = 1;
    dean.state = 'patrol';
    dean.pauseTimer = 0;
    dean.alertLevel = 0;
    dean.timeOutOfSight = 0;
    dean.lastKnownPlayerPos = null;
    dean.barkText = '';
    dean.barkTimer = 0;
    dean.group.position.copy(dean.pos);
    dean.group.rotation.y = dean.facing;
    _deanPath = [];
    // Pick a RANDOM goal room — builds trail + plaque, updates HUD
    chooseGoal();
    // Reset clock
    gameMinutes = 8*60 + 52;
    // Reset HUD
    hudWarningEl.classList.remove('show');
    if (deanBarkEl) deanBarkEl.classList.remove('show');
    bustedEl.classList.remove('show');
    lateEl.classList.remove('show');
    winEl.classList.remove('show');
    pauseEl.classList.remove('show');
    currentRoom = "";
  }

  function restartGame() {
    // Going back through character select gives the player a chance to swap
    // characters between runs (and to confirm/change the goal randomization).
    bustedEl.classList.remove('show');
    lateEl.classList.remove('show');
    winEl.classList.remove('show');
    pauseEl.classList.remove('show');
    hudEl.classList.remove('show');
    gameState = 'title';
    showCharacterSelect();
  }

  function triggerBusted() {
    if (gameState !== 'playing') return;
    gameState = 'busted';
    hudWarningEl.classList.remove('show');
    const bustedBody = document.getElementById('busted-body');
    if (bustedBody) {
      bustedBody.innerHTML =
        `${getInstructorTitle()} has been cornered by Dean Jason.<br>` +
        `The annual FLIP review has begun. The documentation is not finished.<br>` +
        `<i>The next 90 minutes are going to feel like 90 years.</i>`;
    }
    bustedEl.classList.add('show');
    playStinger('busted');
  }
  function triggerLate() {
    if (gameState !== 'playing') return;
    gameState = 'late';
    hudWarningEl.classList.remove('show');
    const lateBody = document.getElementById('late-body');
    if (lateBody) {
      lateBody.innerHTML =
        `It's 9:00 and ${getInstructorTitle()} never made it to class.<br>` +
        `A row of empty desks awaits the absent NTC instructor.`;
    }
    lateEl.classList.add('show');
    playStinger('late');
  }
  function triggerWin() {
    if (gameState !== 'playing') return;
    gameState = 'won';
    hudWarningEl.classList.remove('show');
    // Customize the win-body text to mention the chosen instructor and room
    const winBody = document.getElementById('win-body');
    if (winBody) {
      winBody.innerHTML =
        `${getInstructorTitle()} slides into <b style="color:var(--ntc-gold)">${currentGoal.displayName}</b> with seconds to spare.<br>` +
        `The students rise. The Timberwolves salute their instructor.`;
    }
    winEl.classList.add('show');
    playStinger('win');
  }

  function startGame() {
    // Guard against impatient double-clicks while model scripts are still loading.
    if (gameState === 'loading') return;
    gameState = 'loading';
    if (csPlayBtn) csPlayBtn.disabled = true;
    titleEl.style.display = 'none';
    loadingEl.classList.add('show');
    const bar = document.getElementById('loading-bar');
    if (bar) bar.style.width = '18%';
    initAudio();

    const selectedAssetId = selectedCharacter && selectedCharacter.modelAsset;
    const modelJobs = [];
    if (selectedAssetId) modelJobs.push(loadMeshyAssetScript(selectedAssetId));

    // Load Jason in the background only. If that big model is slow or blocked,
    // gameplay should still start with the fallback dean instead of hanging.
    loadMeshyAssetScript('jason').catch(err => {
      console.warn('Dean Jason model prewarm skipped:', err);
    });

    // Let the loading overlay paint first, then load the selected model asset
    // and perform the actual reset/model swap. If a model file fails, gameplay
    // still starts with the fallback chibi body.
    const begin = () => {
      if (bar) bar.style.width = '38%';
      Promise.all(modelJobs).catch(err => {
        console.warn('Model preparation skipped:', err);
      }).then(() => {
        if (bar) bar.style.width = '72%';
        resetGameState();
        if (bar) bar.style.width = '100%';
        requestAnimationFrame(() => {
          loadingEl.classList.remove('show');
          hudEl.classList.add('show');
          if (csPlayBtn) csPlayBtn.disabled = false;
          gameState = 'playing';
        });
      });
    };
    requestAnimationFrame(() => setTimeout(begin, 0));
  }
  function pauseGame() {
    gameState = 'paused';
    pauseEl.classList.add('show');
  }
  function resumeGame() {
    gameState = 'playing';
    pauseEl.classList.remove('show');
  }
  function goToTitle() {
    gameState = 'title';
    pauseEl.classList.remove('show');
    hudEl.classList.remove('show');
    charSelectEl.classList.remove('show');
    titleEl.style.display = 'flex';
  }

  // ============================================================
  // UPDATE LOOP
  // ============================================================
  const clock = new THREE.Clock();
  let frameCount = 0;

  function update(dt) {
    if (gameState !== 'playing') return;
    frameCount++;

    // ----- INPUT INTENT -----
    let ix = 0, iz = 0;
    if (keys['KeyW'] || keys['ArrowUp']) iz -= 1;
    if (keys['KeyS'] || keys['ArrowDown']) iz += 1;
    if (keys['KeyA'] || keys['ArrowLeft']) ix -= 1;
    if (keys['KeyD'] || keys['ArrowRight']) ix += 1;
    const sprint = !!(keys['ShiftLeft'] || keys['ShiftRight']);

    // Q / E rotate the camera around the player (no mouse needed).
    // This is the only thing that changes camRig.yaw — so WASD remains
    // perfectly stable whenever the player isn't actively turning the camera.
    if (keys['KeyQ']) camRig.yaw -= 1.8 * dt;
    if (keys['KeyE']) camRig.yaw += 1.8 * dt;

    // input is camera-relative
    const mag = Math.hypot(ix, iz);
    let wantX = 0, wantZ = 0;
    if (mag > 0) {
      ix /= mag; iz /= mag;
      // rotate by camera yaw (forward is -Z in cam-yaw=0)
      const c = Math.cos(camRig.yaw), s = Math.sin(camRig.yaw);
      wantX = ix * c + iz * s;
      wantZ = -ix * s + iz * c;
    }

    player.isMoving = (mag > 0.01);
    player.isSprinting = sprint && player.isMoving;
    const targetSpeed = player.isSprinting ? player.sprintSpeed : player.speed;

    // velocity blend
    const accel = 30.0, friction = 18.0;
    const targetVX = wantX * targetSpeed;
    const targetVZ = wantZ * targetSpeed;
    player.vel.x += (targetVX - player.vel.x) * Math.min(1, accel * dt);
    player.vel.z += (targetVZ - player.vel.z) * Math.min(1, accel * dt);
    if (!player.isMoving) {
      player.vel.x -= player.vel.x * Math.min(1, friction * dt);
      player.vel.z -= player.vel.z * Math.min(1, friction * dt);
    }

    // step move + collision (separate axes for smooth wall sliding)
    player.pos.x += player.vel.x * dt;
    resolveCollisions(player.pos, player.radius);
    player.pos.z += player.vel.z * dt;
    resolveCollisions(player.pos, player.radius);

    // face direction of motion
    // Chibi's natural front is +Z; we rotated chibi by π so group-local front = -Z.
    // World forward at rotation.y=θ is (-sin θ, 0, -cos θ).
    // To make that equal motion direction (wantX, wantZ): θ = atan2(-wantX, -wantZ).
    if (player.isMoving) {
      const desired = Math.atan2(-wantX, -wantZ);
      player.targetFacing = desired;
    }
    // shortest angular path
    let delta = player.targetFacing - player.facing;
    while (delta > Math.PI) delta -= Math.PI*2;
    while (delta < -Math.PI) delta += Math.PI*2;
    player.facing += delta * Math.min(1, 12 * dt);

    // bob
    if (player.isMoving) {
      const freq = player.isSprinting ? 11 : 7;
      player.walkBob += dt * freq;
    } else {
      // settle bob
      player.walkBob += dt * 1.0;
    }
    const bobY = player.isMoving ? Math.abs(Math.sin(player.walkBob)) * (player.isSprinting ? 0.08 : 0.05) : 0;
    const tilt = player.isMoving ? Math.sin(player.walkBob) * 0.05 : 0;

    playerGroup.position.set(player.pos.x, bobY, player.pos.z);
    playerGroup.rotation.y = player.facing;
    playerGroup.rotation.z = tilt;

    // footstep audio
    maybeStep(dt);

    // ---- CAMERA ----
    // Camera orbits player at fixed yaw/pitch/distance, with smooth follow.
    // Yaw only changes when player presses Q/E — never via mouse — so WASD is
    // stable and never feels "inverted" by accidental camera rotation.
    const desiredCamX = player.pos.x + Math.sin(camRig.yaw) * camRig.distance * Math.cos(camRig.pitch);
    const desiredCamZ = player.pos.z + Math.cos(camRig.yaw) * camRig.distance * Math.cos(camRig.pitch);
    // Place camera at roughly chest-height behind the player.
    const desiredCamY = 1.5 + camRig.height + Math.sin(-camRig.pitch) * camRig.distance;

    // wall-avoid: shrink distance if cam would clip a wall
    const camToPlayer = new THREE.Vector3(player.pos.x - desiredCamX, 0, player.pos.z - desiredCamZ);
    const camDistTotal = camToPlayer.length();
    if (camDistTotal > 0.01) {
      const dir = new THREE.Vector3().copy(camToPlayer).normalize();
      const origin = new THREE.Vector3(player.pos.x, 0, player.pos.z);
      const outDir = new THREE.Vector3(-dir.x, 0, -dir.z);
      const hit = rayWallHit(origin, outDir, camDistTotal + 0.3);
      if (hit < camDistTotal - 0.05) {
        // pull camera in to where the ray hits, minus a small buffer
        const newDist = Math.max(1.4, hit - 0.35);
        camRig.pos.x = player.pos.x + (-outDir.x) * newDist;
        camRig.pos.z = player.pos.z + (-outDir.z) * newDist;
      } else {
        camRig.pos.x = desiredCamX;
        camRig.pos.z = desiredCamZ;
      }
    }
    camRig.pos.y = desiredCamY;

    // soft lerp to target
    const camLerp = 1 - Math.exp(-dt * 10.0);
    camera.position.lerp(camRig.pos, camLerp);
    // Look at point at the chibi's chest/face — keeps the character framed nicely.
    const lookAt = new THREE.Vector3(player.pos.x, 1.45 + bobY*0.4, player.pos.z);
    camera.lookAt(lookAt);

    // camera bob during sprint
    if (player.isSprinting) {
      camRig.bob += dt * 11;
      camera.position.y += Math.sin(camRig.bob) * 0.02;
    }

    // ---- ROOM TRIGGER + CLOCK ----
    updateRoom();
    // Bell rings at 9:00 AM. We start at 8:52, so we have 8 in-game minutes.
    // Advance the clock at 0.11 in-game min / real sec → ~73 real seconds to 9:00.
    gameMinutes += dt * 0.11;
    updateClockFmt();

    // ---- DEAN AI ----
    updateDean(dt);

    // ---- PICKUPS + PROJECTILES ----
    updatePickups(dt);
    updateProjectiles(dt);

    // ---- WIN CHECK: player has crossed into the chosen goal room ----
    const gb = currentGoal.bounds;
    if (player.pos.x > gb.minX && player.pos.x < gb.maxX &&
        player.pos.z > gb.minZ && player.pos.z < gb.maxZ) {
      triggerWin();
    }

    // ---- LATE CHECK: clock hits 9:00 AM ----
    if (gameMinutes >= 9 * 60) {
      triggerLate();
    }

    // toast fade
    if (toastTimer > 0) {
      toastTimer -= dt;
      if (toastTimer <= 0) hudToastEl.classList.remove('show');
    }

    // ---- FLUORESCENT FLICKER ----
    for (const l of flickerLights) {
      const t = performance.now() * 0.001 + l.userData.flickerSeed;
      // mostly steady with occasional rapid dip
      const noise = Math.sin(t * 13.0) * 0.5 + Math.sin(t * 47.0) * 0.5;
      const dip = (Math.random() < 0.002) ? 0.55 : 1.0;
      l.intensity = l.userData.baseIntensity * (0.92 + 0.08 * noise) * dip;
    }
    // LED blinks
    for (const led of blinkingLEDs) {
      const t = performance.now() * 0.001 + led.userData.blinkSeed;
      led.visible = (Math.sin(t * 2.0) > 0);
    }

    // FINISH-PAW pulse (room destination)
    const pulse = 0.7 + 0.3 * Math.sin(performance.now() * 0.005);
    for (const p of finishPaws) {
      p.material.opacity = pulse;
      const s = 1.0 + 0.18 * Math.sin(performance.now() * 0.005);
      p.scale.set(s, s, s);
    }

    // SIMS DIAMOND animation — slow spin + gentle bob.
    // The diamonds are attached to playerGroup / dean.group, so they inherit
    // their character's world rotation. We *counter-rotate* by negating the
    // character's facing so the diamonds always spin at a steady rate in world
    // space (regardless of which way the character is facing).
    const t = performance.now() * 0.001;
    const spinRate = 1.4;     // rad/sec
    function tickDiamond(d, parentFacing) {
      if (!d) return;
      // World spin: target is t * spinRate. The group already has rotation
      // = parentFacing applied (and possibly tilt). Counter it.
      d.rotation.y = (t * spinRate) - parentFacing;
      // Tilt-cancel: the player group can roll a tiny bit on walkBob; the
      // diamond shouldn't roll with it. Resetting to 0 keeps it level.
      d.rotation.z = 0;
      d.rotation.x = 0;
      // Bob
      const bob = Math.sin(t * 2.0 + (d.userData.bobSeed || 0)) * 0.10;
      // d.position.y is the base height; bob is added at render time via offset
      d.userData.baseY = d.userData.baseY != null ? d.userData.baseY : d.position.y;
      d.position.y = d.userData.baseY + bob;
    }
    tickDiamond(playerDiamond, player.facing);
    tickDiamond(dean.diamond, dean.facing);
  }

  function animate() {
    requestAnimationFrame(animate);
    const dt = Math.min(0.05, clock.getDelta());
    update(dt);
    renderer.render(scene, camera);
  }

  // initial camera placement so title screen has something to look at
  camera.position.set(3, 3.5, 7);
  camera.lookAt(0, 1, 0);

  animate();

  // Expose these for the lightweight GitHub Pages bootstrap in index.html.
  // The game still owns the real UI/gameplay logic; the bootstrap only decides
  // when to load this heavier file.
  window.showCharacterSelect = showCharacterSelect;
  window.startGame = startGame;
  window.__correctCourseGameReady = true;
